#include <stdio.h>
#include <stdint.h>
#include <inttypes.h>

int64_t trailingZeros(int64_t n) {
    int64_t lhs = n;
    int64_t rhs = 0;

    if (lhs == 0) {
        return 0;
    }

    while ((lhs & 1) == 0) {
        lhs = lhs >> 1;
        rhs = rhs + 1;
    }

    return rhs;
}

int main() {
    int64_t test_cases[] = {0, 1, 8, 12, 1024};
    int num_tests = sizeof(test_cases) / sizeof(test_cases[0]);

    for (int i = 0; i < num_tests; i++) {
        int64_t result = trailingZeros(test_cases[i]);
        printf("%" PRId64 "\n", result);
    }

    return 0;
}

