import java.util.*;

public class Solution {
    public static long trailingZeros(long n) {
        if (n == 0) {
            return 0;
        }
        long count = 0;
        long lhs = n;
        long rhs = 2;
        while (true) {
            long remainder = lhs - (lhs / rhs) * rhs;
            if (remainder != 0) {
                break;
            }
            count = count + 1;
            lhs = lhs / rhs;
        }
        return count;
    }

    public static void main(String[] args) {
        // Test case 1: n = 0
        System.out.println(trailingZeros(0));

        // Test case 2: n = 1 (binary 1)
        System.out.println(trailingZeros(1));

        // Test case 3: n = 8 (binary 1000)
        System.out.println(trailingZeros(8));

        // Test case 4: n = 20 (binary 10100)
        System.out.println(trailingZeros(20));

        // Test case 5: n = Long.MAX_VALUE (odd number)
        System.out.println(trailingZeros(Long.MAX_VALUE));

        // Test case 6: n = 1024 (binary 10000000000)
        System.out.println(trailingZeros(1024));

        // Test case 7: n = -8 (negative, binary representation uses two's complement)
        System.out.println(trailingZeros(-8));
    }
}
